exercises.solution:
let y = null;
console.log(y, typeof y); // null 'object'
// typeof null zwraca "object", NIE "null" - to historyczny blad
// w pierwszej wersji JavaScript (1995), nigdy nie naprawiony,
// bo naprawa zlamalaby zbyt wiele istniejacego kodu na swiecie

console.log(undefined == null);  // true - luzne porownanie
console.log(undefined === null); // false - scisle porownanie, rozne typy
// == traktuje null i undefined jako 'rownowazne braki wartosci',
// === odroznia je, bo maja rozny typ (object vs undefined)

function sprawdzWartosc(x) {
  if (x == null) {
    return "pusta";
  }
  return "ma wartosc";
}

console.log(sprawdzWartosc(null));      // "pusta"
console.log(sprawdzWartosc(undefined)); // "pusta"
console.log(sprawdzWartosc(5));         // "ma wartosc"

const zadania = [];

if (zadania) {
  console.log("if(zadania): wchodzi tutaj"); // BLEDNIE - zawsze tutaj, [] jest truthy
}

if (zadania.length > 0) {
  console.log("sa zadania");
} else {
  console.log("brak zadan"); // POPRAWNIE wypisuje sie dla pustej tablicy
}

function domyslnaWartosc(wejscie, domyslna) {
  if (wejscie == null) {
    return domyslna;
  }
  return wejscie;
}

console.log(domyslnaWartosc(undefined, "brak")); // "brak"
console.log(domyslnaWartosc(null, "brak"));      // "brak"
console.log(domyslnaWartosc("dane", "brak"));    // "dane"

const uzytkownik = { imie: "Kasia", adres: null };
console.log(uzytkownik);
// { imie: 'Kasia', adres: null }
// null jawnie komunikuje: SPRAWDZONO, uzytkownik SWIADOMIE nie ma adresu -
// pominiecie wlasciwosci adres w ogole bylby DWUZNACZNE: czy nikt jej
// jeszcze nie ustawil, czy uzytkownik faktycznie NIE MA adresu?

function policzPrawdziwe(tablica) {
  let licznik = 0;
  for (let i = 0; i < tablica.length; i++) {
    if (Boolean(tablica[i])) {
      licznik++;
    }
  }
  return licznik;
}

console.log(policzPrawdziwe([0, 1, "", "tekst", null, [], NaN])); // 3
// truthy: 1, "tekst", [] (pusta tablica JEST truthy!) - stad wynik 3

function jestPusteLubZero(x) {
  return !x;
}

console.log(jestPusteLubZero(""));      // true
console.log(jestPusteLubZero(0));       // true
console.log(jestPusteLubZero(null));    // true
console.log(jestPusteLubZero("tekst")); // false

const konfiguracja = {};

if (konfiguracja) {
  console.log("konfiguracja jest truthy");
} else {
  console.log("to sie nie wykona");
}
// pusty obiekt {} jest truthy z DOKLADNIE tego samego powodu co pusta
// tablica [] - to wciaz OBIEKT, a wszystkie obiekty w JS sa truthy,
// niezaleznie od tego, czy maja jakiekolwiek wlasciwosci

function pierwszaPrawdziwaWartosc(tablica) {
  for (let i = 0; i < tablica.length; i++) {
    if (Boolean(tablica[i])) {
      return tablica[i];
    }
  }
  return null;
}

console.log(pierwszaPrawdziwaWartosc([0, "", null, 5, "tekst"])); // 5

let wynikWyszukiwania = null;

if (wynikWyszukiwania === null) {
  console.log("Brak wynikow");
} else {
  console.log("Znaleziono");
}
// "Brak wynikow"

function test(parametr) {
  if (typeof parametr === "undefined") {
    return "brak argumentu";
  }
  return "argument: " + parametr;
}

console.log(test());  // "brak argumentu"
console.log(test(5)); // "argument: 5"

function podzielNaFalsyTruthy(wartosci) {
  const falsy = [];
  const truthy = [];
  for (let i = 0; i < wartosci.length; i++) {
    if (Boolean(wartosci[i])) {
      truthy.push(wartosci[i]);
    } else {
      falsy.push(wartosci[i]);
    }
  }
  return { falsy, truthy };
}

console.log(podzielNaFalsyTruthy([null, undefined, 0, "", false, NaN, 1, "a"]));
// { falsy: [null, undefined, 0, '', false, NaN], truthy: [1, 'a'] }

const uzytkownik = { imie: "Ala", wiek: undefined };
console.log(typeof uzytkownik.wiek); // "undefined"
console.log("wiek" in uzytkownik);   // true - klucz ISTNIEJE, mimo wartosci undefined

function bezpiecznaDlugosc(tekst) {
  return tekst?.length ?? 0;
}

console.log(bezpiecznaDlugosc("test")); // 4
console.log(bezpiecznaDlugosc(null));   // 0

function policzNullowe(tablica) {
  let licznik = 0;
  for (let i = 0; i < tablica.length; i++) {
    if (tablica[i] === null) {
      licznik++;
    }
  }
  return licznik;
}

console.log(policzNullowe([null, undefined, 0, null, "a", null])); // 3

function aktywujKonto(dane) {
  return dane.status ? "aktywne" : "nieaktywne";
}

console.log(aktywujKonto({ status: 1 })); // "aktywne"
console.log(aktywujKonto({ status: 0 })); // "nieaktywne"
console.log(aktywujKonto({}));            // "nieaktywne" - status jest undefined, falsy

function sprawdzTyp(wartosc) {
  return typeof wartosc;
}

const wartosci = [5, "tekst", true, undefined, null, [], {}];
for (let i = 0; i < wartosci.length; i++) {
  console.log(sprawdzTyp(wartosci[i]));
}
// number string boolean undefined object object object

function test() {
  let wynik = undefined;
  if (false) {
    wynik = "cos";
  }
  return wynik;
}

console.log(test(), typeof test()); // undefined 'undefined'

function zwroc_null() {
  return null;
}

function zwroc_nic() {
  // brak return
}

console.log(zwroc_null(), typeof zwroc_null()); // null 'object'
console.log(zwroc_nic(), typeof zwroc_nic());    // undefined 'undefined'

const ustawienia = { motyw: null, jezyk: undefined, powiadomienia: true };
console.log(Object.keys(ustawienia)); // ['motyw', 'jezyk', 'powiadomienia']
// wszystkie trzy klucze ISTNIEJA w obiekcie, niezaleznie od tego,
// ze dwa z nich maja 'puste' wartosci (null i undefined)

function policzWypelnioneFormularze(formularze) {
  let licznik = 0;
  for (let i = 0; i < formularze.length; i++) {
    if (Boolean(formularze[i].wypelniony)) {
      licznik++;
    }
  }
  return licznik;
}

console.log(policzWypelnioneFormularze([
  { wypelniony: true },
  { wypelniony: false },
  { wypelniony: true }
])); // 2

function test(a, b) {
  return a && b;
}

console.log(test(0, "tekst"));  // 0 - pierwsza falsy wartosc
console.log(test("a", "b"));    // "b" - obie truthy, zwraca OSTATNIA
console.log(test(null, 5));     // null - pierwsza falsy wartosc
// && NIE zwraca zawsze true/false - zwraca KONKRETNA wartosc,
// ktora zdecydowala o wyniku calego wyrazenia

function test(a, b) {
  return a || b;
}

console.log(test(0, "domyslna"));         // "domyslna" - 0 jest falsy
console.log(test("", "domyslna"));        // "domyslna" - pusty string jest falsy
console.log(test("wartosc", "domyslna")); // "wartosc" - truthy, wiec zwraca 'a'
// typowe (choc niedoskonale - patrz operator ?? w rozdziale 5)
// zastosowanie || do ustawiania wartosci domyslnej,
// gdy pierwsza wartosc jest 'pusta' w sensie falsy

function jestPoprawnyWiek(wiek) {
  return typeof wiek === "number" && !Number.isNaN(wiek);
}

console.log(jestPoprawnyWiek(25));        // true
console.log(jestPoprawnyWiek(NaN));       // false
console.log(jestPoprawnyWiek("abc"));     // false
console.log(jestPoprawnyWiek(undefined)); // false

console.log(null == 0);      // false
console.log(undefined == 0); // false
// mimo ze null, undefined i 0 sa WSZYSTKIE falsy w kontekscie logicznym,
// operator == null/undefined ma SPECJALNA regule: null i undefined sa
// rowne TYLKO sobie nawzajem (i sobie samym) przez == - nigdy innym
// falsy wartosciom jak 0, '', czy false

function pobierzPierwszyZnaleziony(tablica) {
  for (let i = 0; i < tablica.length; i++) {
    if (tablica[i] != null) {
      return tablica[i];
    }
  }
  return undefined;
}

console.log(pobierzPierwszyZnaleziony([null, undefined, 0, "znaleziono"])); // 0

